/*
 * @module   sigma_rom
 * @brief    SwiGLU sigmoid lookup: sigma(x/16) in Q.6 for every int8 gate code x (Vectorized, combinational).
 * @details  silu(x) = x * sigma(x) needs sigma only at the 256 int8 gate codes, so the whole
 *           alpha -> exp -> +1 -> ln -> neg -> exp chain collapses to one table read.
 *           The 256 entries equal the output of that chain at FRAC_W=6 (flat alpha=1, the shared ln unit at
 *           BITS=6, x<0 mapped through 64 - recip), generated by tools/models/vpu_ops.py::_sigma_table(6, RECOMMENDED)
 *           and checked against it by the tr_swiglu_int regression (golden: sw_silu() / SW_SIGMA in tr_math_model.hpp).
 *           Values are 6 bits unsigned (1..63; the table never reaches 64 = 1.0).
 *
 * @param    N   Vector dimension.
 */
module sigma_rom #(
    parameter int N = 8
)(
    input  logic signed [7:0] x     [N],
    output logic        [5:0] sigma [N]
);

    function automatic logic [5:0] lookup(input logic signed [7:0] c);
